<?php
declare(strict_types=1);
require_once __DIR__.'/config/database.php';
$error=null;$m=[];$recent=[];
try{$pdo=business_db();security_step17_ensure($pdo);$user=security_step17_current_user($pdo);$ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$q=function(string $sql,array $args=[])use($pdo){$s=$pdo->prepare($sql);$s->execute($args);return$s;};$m['users']=(int)$q("SELECT COUNT(*) FROM system_users u JOIN organization_user_access a ON a.user_id=u.id AND a.organization_id=? WHERE u.is_active=1 AND a.is_active=1",[$orgId])->fetchColumn();$m['admins']=security_step17_admin_count($pdo,$orgId);$m['sessions']=(int)$q("SELECT COUNT(*) FROM security_sessions WHERE organization_id=? AND revoked_at IS NULL AND expires_at>NOW()",[$orgId])->fetchColumn();$m['failed24']=(int)$q("SELECT COUNT(*) FROM security_login_attempts WHERE organization_id=? AND was_successful=0 AND attempted_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR)",[$orgId])->fetchColumn();$m['roles']=(int)$q("SELECT COUNT(*) FROM security_roles WHERE organization_id=? AND is_active=1",[$orgId])->fetchColumn();$m['permissions']=(int)$pdo->query("SELECT COUNT(*) FROM security_permissions WHERE is_active=1")->fetchColumn();$m['idle']=security_step17_setting($pdo,$orgId,'idle_timeout_seconds',1800);$m['absolute']=security_step17_setting($pdo,$orgId,'absolute_timeout_seconds',43200);$s=$q("SELECT a.event_type,a.entity_type,a.entity_id,a.created_at,u.full_name FROM audit_logs a LEFT JOIN system_users u ON u.id=a.user_id WHERE a.organization_id=? AND a.event_type LIKE 'security_%' ORDER BY a.id DESC LIMIT 12",[$orgId]);$recent=$s->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
function sc17f(int $seconds):string{return $seconds>=3600?number_format($seconds/3600,1).' hr':number_format($seconds/60).' min';}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Security Center - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="index.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 17 • Security & Access Control</small></span></a><div class="os-top-actions"><a class="os-btn" href="security_audit.php">Security Audit</a><a class="os-btn" href="security_sessions.php">Sessions</a><a class="os-btn primary" href="user_management.php">Users</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Security</div><nav class="os-nav"><a class="active" href="security_center.php"><i class="dot"></i>Security Center</a><a href="user_management.php"><i class="dot"></i>Users</a><a href="permission_matrix.php"><i class="dot"></i>Permissions</a><a href="security_sessions.php"><i class="dot"></i>Sessions</a><a href="security_audit.php"><i class="dot"></i>Audit</a><a href="password_change.php"><i class="dot"></i>My Password</a><a href="step17_audit.php"><i class="dot"></i>STEP 17 Audit</a></nav><div class="os-sidebar-status"><b>Signed in</b><span><?= security_step17_h(($user['full_name']??'').' • '.strtoupper((string)($user['role_code']??''))) ?></span></div></aside><main class="os-main"><section class="os-hero s10-hero"><div class="os-kicker">STEP 17 • IDENTITY + RBAC + SESSION SECURITY</div><h1>Users, roles, permissions and active sessions are now centrally controlled.</h1><p>No default password exists. Access is organization-scoped, sensitive Finance/Security routes are permission-gated, and login/session events remain auditable.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'SECURITY LAYER LIVE':'Review required' ?></span><span class="os-chip good">4 system roles</span><span class="os-chip">Idle <?= sc17f((int)($m['idle']??1800)) ?></span><span class="os-chip">Absolute <?= sc17f((int)($m['absolute']??43200)) ?></span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Security diagnostic:</strong> <?= security_step17_h($error) ?></div><?php endif;?><?php if(!$error):?><section class="s10-kpis"><div class="s10-kpi"><small>Active Users</small><strong><?= (int)$m['users'] ?></strong><span><?= (int)$m['admins'] ?> administrator(s)</span></div><div class="s10-kpi"><small>Active Sessions</small><strong><?= (int)$m['sessions'] ?></strong><span>revocable server-side sessions</span></div><div class="s10-kpi"><small>Failed Logins • 24h</small><strong><?= (int)$m['failed24'] ?></strong><span>throttled after repeated failures</span></div><div class="s10-kpi"><small>Permissions</small><strong><?= (int)$m['permissions'] ?></strong><span><?= (int)$m['roles'] ?> roles</span></div></section><section class="s10-grid"><article class="s10-card s10-span-8"><div class="os-title-row"><div><h2>Security Workspaces</h2><p>Use explicit controls instead of editing database access manually.</p></div></div><div class="os-report-grid"><a class="os-report" href="user_management.php"><div class="os-report-head"><b>User Management</b><em>ADMIN</em></div><span>Create, activate/deactivate, role-change and password-reset users.</span><small>Open →</small></a><a class="os-report" href="permission_matrix.php"><div class="os-report-head"><b>Permission Matrix</b><em>RBAC</em></div><span>Configure Manager, Staff and Viewer permissions.</span><small>Open →</small></a><a class="os-report" href="security_sessions.php"><div class="os-report-head"><b>Active Sessions</b><em>REVOKE</em></div><span>See devices/sessions and revoke access immediately.</span><small>Open →</small></a><a class="os-report" href="security_audit.php"><div class="os-report-head"><b>Security Audit</b><em>TRACE</em></div><span>Login failures, sign-ins, role changes and access denials.</span><small>Open →</small></a></div></article><aside class="s10-card s10-span-4"><h2>Recent Security Events</h2><div class="s10-list"><?php foreach($recent as $r):?><div class="s10-row"><div><b><?= security_step17_h($r['event_type']) ?></b><small><?= security_step17_h($r['full_name']?:'System/unknown user') ?></small></div><span><?= security_step17_h(substr((string)$r['created_at'],0,16)) ?></span></div><?php endforeach;?><?php if(!$recent):?><p>No security events yet.</p><?php endif;?></div></aside></section><div class="os-footer-note"><strong>Security policy:</strong> authentication data never contains plaintext passwords; access changes revoke affected active sessions so new permissions take effect on the next sign-in.</div><?php endif;?></main></div></body></html>